<?php require_once __DIR__.'/../../app/layout.php';$a=require_admin();$allowed=['org_name','short_name','address','phone','email','website','membership_fee','membership_validity','membership_description','upi_id','bank_details','footer_text','ack_footer','authorised_signatory_name','authorised_signatory_designation'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach($allowed as $key)if(isset($_POST[$key]))$pdo->prepare('INSERT INTO site_settings (`key`,`value`) VALUES (?,?) ON DUPLICATE KEY UPDATE `value`=VALUES(`value`)')->execute([$key,trim($_POST[$key])]);foreach(['home_intro','mission','about','contact'] as $key)$pdo->prepare('UPDATE cms_content SET body=? WHERE `key`=?')->execute([trim($_POST[$key]??''),$key]);audit($pdo,$a['id'],'settings_updated','settings',1);flash('Settings saved.');redirect('/admin/settings.php');}$content=[];$st=$pdo->query('SELECT `key`,body FROM cms_content');foreach($st as $row)$content[$row['key']]=$row['body'];header_html('Settings');?><h1>Settings & website content</h1><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><?php foreach($allowed as $key):?><label><?=e(ucwords(str_replace('_',' ',$key)))?><input name="<?=$key?>" value="<?=e(setting($pdo,$key))?>"></label><?php endforeach;?><?php foreach(['home_intro','mission','about','contact'] as $key):?><label><?=e(ucwords(str_replace('_',' ',$key)))?><textarea name="<?=$key?>"><?=e($content[$key]??'')?></textarea></label><?php endforeach;?><button>Save settings</button></form><?php footer_html();
